import express from 'express';
import request from 'supertest';
import {createChatRoutes} from './chats.js';
import {createChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import {createMockProvider} from '../../providers/mock/index.js';

it('refuses chat creation without authentication @specs/hal-engine-chat-routes/spec.md#10', async () => {
  const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'Assistant'}));
  const app = express();
  app.use(express.json());
  app.use('/chats', createChatRoutes(orchestrator, new InMemorySessionStore()));

  const response = await request(app).post('/chats');

  expect({status: response.status, body: response.body}).toEqual({status: 401, body: {error: 'Unauthorized'}});
});
EOF
